	public Stream<DynamicTest> tests(boolean supportsTripleTerms) throws IOException {
		List<Vector> vectors = readVectors();
		if (vectors.size() != 126) {
			throw new IOException("Expected 126 BNR conformance vectors, found " + vectors.size());
		}
		Set<String> ids = new HashSet<>();
		for (Vector vector : vectors) {
			if (!ids.add(vector.id())) {
				throw new IOException("Duplicate BNR conformance vector " + vector.id());
			}
		}
		Set<String> expectedIds = IntStream.rangeClosed(1, 126)
				.mapToObj(number -> "BNR-%03d".formatted(number))
				.collect(Collectors.toSet());
		if (!ids.equals(expectedIds)) {
			throw new IOException("BNR vector IDs must be exactly BNR-001 through BNR-126");
		}
		if (!ids.containsAll(STATIC_REJECTION_IDS)) {
			throw new IOException("Missing one or more explicitly classified static BNR rejection vectors");
		}
		Stream<DynamicTest> vectorTests = vectors.stream()
				.map(vector -> makeTest(vector.id() + " " + vector.title(), connection -> {
					Assumptions.assumeTrue(supportsTripleTerms || STATIC_REJECTION_IDS.contains(vector.id())
							|| !TRIPLE_TERM_REQUIRED_IDS.contains(vector.id()),
							"NativeStore does not support triple terms; this vector is explicitly unsupported");
					assertVector(vector, connection);
				}));
		return Stream.concat(vectorTests, nestedReferenceClosureTests(supportsTripleTerms));
	}

	private Stream<DynamicTest> nestedReferenceClosureTests(boolean supportsTripleTerms) {
		return IntStream.rangeClosed(1, 8)
				.mapToObj(depth -> makeTest("BNR generated nested reference closure depth " + depth, connection -> {
					Assumptions.assumeTrue(supportsTripleTerms,
							"NativeStore does not support triple terms; this generated case is explicitly unsupported");
					connection.setQueryParseOptions(QueryParseOptions.DEFAULT);
					loadFixture("base", connection);
					NestedReferenceTerm nested = nestedReferenceTerm(depth, connection.getValueFactory());
					String query = "SELECT ?term ?graph ?equal ?present WHERE { "
							+ "VALUES (?term ?graph) { (" + nested.sparql() + " <_:g>) } "
							+ "BIND(sameTerm(?term, " + nested.sparql() + ") AS ?equal) "
							+ "OPTIONAL { VALUES ?present { <_:bnode1> } } "
							+ "FILTER(BOUND(?present)) "
							+ "{ VALUES ?branch { true } } UNION { VALUES ?branch { false } } "
							+ "FILTER(?branch = ?equal) "
							+ "MINUS { VALUES ?term { <urn:not-a-triple-term> } } }";
					TupleQuery tupleQuery = connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
					List<BindingSet> rows = new ArrayList<>();
					try (var result = tupleQuery.evaluate()) {
						while (result.hasNext()) {
							rows.add(result.next());
						}
					}
					assertEquals(1, rows.size());
					BindingSet row = rows.get(0);
					assertEquals(nested.value(), row.getValue("term"));
					assertEquals(connection.getValueFactory().createBNode("g"), row.getValue("graph"));
					assertEquals(connection.getValueFactory().createLiteral(true), row.getValue("equal"));
					assertEquals(connection.getValueFactory().createBNode("bnode1"), row.getValue("present"));
				}));
	}

	private static NestedReferenceTerm nestedReferenceTerm(int depth, ValueFactory vf) {
		String sparql = "<<( <_:bnode1> <urn:p> <_:bnode2> )>>";
		Value value = vf.createTripleTerm(vf.createBNode("bnode1"), vf.createIRI("urn:p"), vf.createBNode("bnode2"));
		for (int level = 2; level <= depth; level++) {
			IRI contains = vf.createIRI("urn:contains");
			IRI outer = vf.createIRI("urn:outer" + level);
			sparql = "<<( <" + outer + "> <urn:contains> " + sparql + " )>>";
			value = vf.createTripleTerm(outer, contains, value);
		}
		return new NestedReferenceTerm(sparql, value);
	}

	private static void assertVector(Vector vector, RepositoryConnection connection) throws Exception {
		connection.setQueryParseOptions("strict-SPARQL-1.2".equals(vector.mode())
				? QueryParseOptions.STRICT
				: QueryParseOptions.DEFAULT);
		ValueFactory vf = connection.getValueFactory();
		loadFixture(vector.fixture(), connection);
		if ("BNR-111".equals(vector.id())) {
			connection.add(vf.createIRI("urn:s"), vf.createIRI("urn:value"), vf.createLiteral("7", XSD.INTEGER),
					vf.createIRI("urn:source"));
		}
		MockFederatedService mockService = configureMockService(vector, connection, vf);
		Set<Statement> before = statements(connection);

		if (STATIC_REJECTION_IDS.contains(vector.id())) {
			String request = vector.requests().get(0);
			assertThrows(MalformedQueryException.class, () -> prepare(request, connection));
			assertEquals(before, statements(connection), vector.id() + " must reject before changing the dataset");
			return;
		}

		List<ExecutionResult> results = new ArrayList<>();
		if ("BNR-120".equals(vector.id())) {
			BooleanQuery ask = connection.prepareBooleanQuery(QueryLanguage.SPARQL, vector.requests().get(0));
			results.add(ExecutionResult.booleanResult(ask.evaluate()));
			Update update = connection.prepareUpdate(QueryLanguage.SPARQL, vector.requests().get(1));
			executeUpdate(update);
			results.add(ExecutionResult.updateResult());
			results.add(ExecutionResult.booleanResult(ask.evaluate()));
		} else {
			LocalDocumentSource documentSource = "BNR-119".equals(vector.id())
					? new LocalDocumentSource()
					: null;
			try {
				for (String originalRequest : vector.requests()) {
					String request = documentSource == null ? originalRequest
							: documentSource.localize(originalRequest);
					try {
						results.add(execute(request, connection));
					} catch (QueryEvaluationException e) {
						if ("BNR-125".equals(vector.id())) {
							assertUnsupportedIdentity(e);
							assertFalse(mockService.sawBnodeInput(),
									"The remote service must not receive an unsupported local BNode identity");
							return;
						}
						if ("BNR-066".equals(vector.id())) {
							assertNotNull(e.getMessage());
							results.add(ExecutionResult.updateResult());
							continue;
						}
						throw e;
					}
				}
			} finally {
				if (documentSource != null) {
					documentSource.close();
				}
			}
		}

		assertOutcome(vector, results, before, statements(connection), connection, vf, mockService);
	}

	private static void loadFixture(String fixtureName, RepositoryConnection connection) throws IOException {
		@SuppressWarnings("unchecked")
		Map<String, Object> root = (Map<String, Object>) readCatalogue();
		@SuppressWarnings("unchecked")
		Map<String, Object> fixtures = (Map<String, Object>) root.get("fixtures");
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> statements = (List<Map<String, Object>>) fixtures.get(fixtureName);
		if (statements == null) {
			throw new IOException("Missing fixture " + fixtureName);
		}
		ValueFactory vf = connection.getValueFactory();
		for (Map<String, Object> statement : statements) {
			Resource subject = (Resource) fixtureValue(object(statement.get("subject")), vf);
			IRI predicate = (IRI) fixtureValue(object(statement.get("predicate")), vf);
			Value object = fixtureValue(object(statement.get("object")), vf);
			Object graphValue = statement.get("graph");
			if (graphValue == null) {
				connection.add(subject, predicate, object);
			} else {
				connection.add(subject, predicate, object,
						(Resource) fixtureValue(object(graphValue), vf));
			}
		}
	}

	private static Value fixtureValue(Map<String, Object> term, ValueFactory vf) {
		return switch (string(term, "type")) {
		case "bnode" -> vf.createBNode(string(term, "id"));
		case "iri" -> vf.createIRI(string(term, "value"));
		case "literal" -> vf.createLiteral(string(term, "value"), vf.createIRI(string(term, "datatype")));
		default -> throw new IllegalArgumentException("Unknown fixture term " + term);
		};
	}

	private static ExecutionResult execute(String request, RepositoryConnection connection) throws Exception {
		if (!isQuery(request)) {
			Update update = connection.prepareUpdate(QueryLanguage.SPARQL, request);
			executeUpdate(update);
			return ExecutionResult.updateResult();
		}
		Query query = connection.prepareQuery(QueryLanguage.SPARQL, request);
		if (query instanceof BooleanQuery booleanQuery) {
			return ExecutionResult.booleanResult(booleanQuery.evaluate());
		}
		if (query instanceof TupleQuery tupleQuery) {
			List<BindingSet> rows = new ArrayList<>();
			try (var result = tupleQuery.evaluate()) {
				while (result.hasNext()) {
					rows.add(result.next());
				}
			}
			return ExecutionResult.tupleResult(rows);
		}
		if (query instanceof GraphQuery graphQuery) {
			Set<Statement> graph = new HashSet<>();
			try (var result = graphQuery.evaluate()) {
				while (result.hasNext()) {
					graph.add(result.next());
				}
			}
			return ExecutionResult.graphResult(graph);
		}
		throw new AssertionError("Unexpected query form " + query.getClass().getName());
	}

	private static void executeUpdate(Update update) {
		SimpleDataset dataset = new SimpleDataset();
		dataset.addDefaultRemoveGraph(RDF4J.NIL);
		update.setDataset(dataset);
		update.execute();
	}

	private static void prepare(String request, RepositoryConnection connection) {
		if (isQuery(request)) {
			connection.prepareQuery(QueryLanguage.SPARQL, request);
		} else {
			connection.prepareUpdate(QueryLanguage.SPARQL, request);
		}
	}

	private static boolean isQuery(String request) {
		String remainder = stripPrologue(request).toUpperCase(Locale.ROOT);
		return remainder.startsWith("SELECT") || remainder.startsWith("ASK")
				|| remainder.startsWith("CONSTRUCT") || remainder.startsWith("DESCRIBE");
	}

	private static String stripPrologue(String request) {
		int offset = 0;
		while (offset < request.length()) {
			String remainder = request.substring(offset).stripLeading();
			int leading = request.substring(offset).length() - remainder.length();
			offset += leading;
			String upper = remainder.toUpperCase(Locale.ROOT);
			int valueStart;
			if (upper.startsWith("BASE ")) {
				valueStart = remainder.indexOf('<');
				int end = remainder.indexOf('>', valueStart + 1);
				if (valueStart < 0 || end < 0) {
					return remainder;
				}
				offset += end + 1;
			} else if (upper.startsWith("PREFIX ")) {
				valueStart = remainder.indexOf('<');
				int end = remainder.indexOf('>', valueStart + 1);
				if (valueStart < 0 || end < 0) {
					return remainder;
				}
				offset += end + 1;
			} else if (upper.startsWith("VERSION ")) {
				valueStart = remainder.indexOf('"');
				int end = remainder.indexOf('"', valueStart + 1);
				if (valueStart < 0 || end < 0) {
					return remainder;
				}
				offset += end + 1;
			} else {
				return remainder;
			}
		}
		return "";
	}

