	private static void assertDescribeFixedMatchesBoundNode(ExecutionResult result, RepositoryConnection connection,
			ValueFactory vf) throws Exception {
		assertGraph(result, null);
		assertTrue(
				result.graph().stream().anyMatch(statement -> vf.createBNode("bnode1").equals(statement.getSubject())));
		GraphQuery boundDescribe = connection.prepareGraphQuery(
				"DESCRIBE ?s WHERE { VALUES ?s { <_:bnode1> } }");
		Set<Statement> boundDescription = new HashSet<>();
		try (var queryResult = boundDescribe.evaluate()) {
			while (queryResult.hasNext()) {
				boundDescription.add(queryResult.next());
			}
		}
		assertEquals(boundDescription, result.graph(),
				"Fixed-reference DESCRIBE should match this implementation's variable-bound policy");
	}

	private static void assertConstructWithFixedAndFreshNodes(ExecutionResult result, Set<Statement> before,
			Set<Statement> after, ValueFactory vf) {
		assertGraph(result, 6);
		assertEquals(before, after, "CONSTRUCT must not mutate the repository");
		BNode fixed = vf.createBNode("fixed");
		Set<Statement> expected = new HashSet<>();
		IRI seen = vf.createIRI("urn:seen");
		IRI owner = vf.createIRI("urn:owner");
		IRI value = vf.createIRI("urn:value");
		for (Literal literal : List.of(vf.createLiteral("1", XSD.INTEGER), vf.createLiteral("2", XSD.INTEGER))) {
			expected.add(vf.createStatement(fixed, seen, literal));
		}
		Set<Resource> generated = result.graph()
				.stream()
				.filter(statement -> vf.createIRI("urn:owner").equals(statement.getPredicate()))
				.map(Statement::getSubject)
				.collect(Collectors.toSet());
		assertEquals(2, generated.size());
		assertTrue(generated.stream().allMatch(BNode.class::isInstance));
		assertFalse(generated.contains(fixed));
		for (Resource subject : generated) {
			Set<Value> ownerValues = result.graph()
					.stream()
					.filter(statement -> subject.equals(statement.getSubject())
							&& owner.equals(statement.getPredicate()))
					.map(Statement::getObject)
					.collect(Collectors.toSet());
			assertEquals(Set.of(fixed), ownerValues);
			Set<Value> values = result.graph()
					.stream()
					.filter(statement -> subject.equals(statement.getSubject())
							&& value.equals(statement.getPredicate()))
					.map(Statement::getObject)
					.collect(Collectors.toSet());
			assertEquals(1, values.size());
			Value literal = values.iterator().next();
			assertTrue(
					Set.of(vf.createLiteral("1", XSD.INTEGER), vf.createLiteral("2", XSD.INTEGER)).contains(literal));
			expected.add(vf.createStatement(subject, owner, fixed));
			expected.add(vf.createStatement(subject, value, literal));
		}
		assertEquals(Set.of(vf.createLiteral("1", XSD.INTEGER), vf.createLiteral("2", XSD.INTEGER)),
				generated.stream()
						.flatMap(subject -> result.graph()
								.stream()
								.filter(statement -> subject.equals(statement.getSubject())
										&& value.equals(statement.getPredicate()))
								.map(Statement::getObject))
						.collect(Collectors.toSet()));
		assertEquals(expected, result.graph());
	}

	private static void assertFreshSubjects(ExecutionResult result, int count, Set<Value> existingSubjects,
			ValueFactory vf) {
		assertGraph(result, count);
		Set<Resource> subjects = result.graph()
				.stream()
				.map(Statement::getSubject)
				.collect(Collectors.toSet());
		assertEquals(count, subjects.size());
		assertTrue(subjects.stream().allMatch(BNode.class::isInstance));
		assertTrue(subjects.stream().noneMatch(existingSubjects::contains));
		assertTrue(result.graph()
				.stream()
				.allMatch(statement -> vf.createIRI("urn:p").equals(statement.getPredicate())
						&& vf.createLiteral("v").equals(statement.getObject())));
	}

	private static void assertFreshConstructSubjects(ExecutionResult result, int count, BNode fixedObject) {
		assertGraph(result, count);
		Set<Resource> subjects = result.graph()
				.stream()
				.map(Statement::getSubject)
				.collect(Collectors.toSet());
		assertEquals(count, subjects.size());
		assertTrue(subjects.stream().allMatch(BNode.class::isInstance));
		assertTrue(
				result.graph().stream().allMatch(statement -> "urn:p".equals(statement.getPredicate().stringValue())));
		assertTrue(result.graph().stream().allMatch(statement -> fixedObject.equals(statement.getObject())));
	}

