	private static void assertFreshPointingTo(Set<Statement> after, ValueFactory vf, String fixedId, int count) {
		assertEquals(count, after.size());
		BNode fixed = vf.createBNode(fixedId);
		Set<Statement> points = after.stream()
				.filter(statement -> vf.createIRI("urn:pointsTo").equals(statement.getPredicate()))
				.collect(Collectors.toSet());
		assertEquals(count, points.size());
		Set<Resource> subjects = new HashSet<>();
		for (Statement point : points) {
			assertTrue(point.getSubject() instanceof BNode);
			assertEquals(fixed, point.getObject());
			assertNotEquals(fixed, point.getSubject());
			subjects.add(point.getSubject());
		}
		assertEquals(count, subjects.size());
	}

