	private static void assertGraphTransferOutcome(String id, Set<Statement> before, Set<Statement> after,
			ValueFactory vf) {
		BNode graph = vf.createBNode("g");
		Statement named = vf.createStatement(vf.createBNode("bnode1"), vf.createIRI("urn:n"),
				vf.createLiteral("named"), graph);
		Set<Statement> expected = new HashSet<>(before);
		switch (id) {
		case "BNR-109" -> expected.add(vf.createStatement(graph, vf.createIRI("urn:self"), graph, graph));
		case "BNR-112" -> {
			expected.add(vf.createStatement(vf.createBNode("bnode1"), vf.createIRI("urn:n"),
					vf.createLiteral("named"), vf.createBNode("copy")));
		}
		case "BNR-113" -> {
			expected.remove(named);
			expected.add(vf.createStatement(vf.createBNode("bnode1"), vf.createIRI("urn:n"),
					vf.createLiteral("named"), vf.createBNode("moved")));
		}
		case "BNR-114" -> expected.add(vf.createStatement(vf.createBNode("bnode1"), vf.createIRI("urn:n"),
				vf.createLiteral("named"), vf.createBNode("added")));
		case "BNR-115" -> {
		}
		default -> throw new AssertionError("Unexpected graph transfer vector " + id);
		}
		assertEquals(expected, after);
	}

