	private static void assertIdentityRoundTrip(List<ExecutionResult> results, RepositoryConnection connection,
			ValueFactory vf) throws Exception {
		assertEquals(2, results.size());
		assertRows(results.get(0), 1);
		assertBoolean(results.get(1), true);
		Value returned = value(results.get(0), 0, "s");
		assertTrue(returned instanceof BNode);
		BNode parsed = jsonRoundTrip((BNode) returned, vf);
		assertEquals(vf.createBNode("bnode1").getID(), parsed.getID());
		BooleanQuery ask = connection.prepareBooleanQuery(QueryLanguage.SPARQL,
				"ASK { <_:" + parsed.getID() + "> <urn:link> <_:bnode2> }");
		assertTrue(ask.evaluate(), "The ID returned by SPARQL/JSON must remain usable as a BNR reference");
	}

	private static BNode jsonRoundTrip(BNode value, ValueFactory vf) throws IOException {
		List<String> bindingNames = List.of("value");
		IteratingTupleQueryResult result = new IteratingTupleQueryResult(bindingNames,
				List.of(new ListBindingSet(bindingNames, value)));
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		QueryResultIO.writeTuple(result, TupleQueryResultFormat.JSON, output);
		QueryResultCollector collector = new QueryResultCollector();
		QueryResultIO.parseTuple(new ByteArrayInputStream(output.toByteArray()), TupleQueryResultFormat.JSON, collector,
				vf);
		Value parsed = collector.getBindingSets().get(0).getValue("value");
		assertTrue(parsed instanceof BNode, "SPARQL/JSON must preserve a BNode result as a BNode");
		return (BNode) parsed;
	}

	private static void assertNoBNodeResult(List<ExecutionResult> results, ValueFactory vf) {
		for (ExecutionResult result : results) {
			if (result.kind() == ResultKind.TUPLE) {
				for (BindingSet row : result.rows()) {
					for (Binding binding : row) {
						assertFalse(binding.getValue() instanceof BNode,
								"IRI(\"_:b\") must not create a blank node");
					}
				}
			}
		}
	}

